using Suishouyi.Core;
namespace Suishouyi.App;
internal sealed class ResultWindow:Form {
 readonly Dictionary<TaskMode,AIResult> results=new();readonly Label heading=new(),source=new();readonly RichTextBox body=new(),original=new();readonly Button translate=new(),explain=new(),copy=new(),cancel=new(),retry=new(),expand=new(),login=new(),chooseModel=new();readonly ComboBox models=new();bool changing;
 public string OriginalText {get;}public TaskMode Mode {get;private set;}public bool Busy {get;private set;}
 public event Action<TaskMode>? ModeRequested;public event Action? CancelRequested;public event Action<string>? ModelSelected;public event Action? RetryRequested;public event Action? LoginRequested;public event Action? ModelsRequested;
 public ResultWindow(string text,TaskMode mode,IReadOnlyList<string> catalog,string selected,string theme) {
  OriginalText=text;Mode=mode;Text="随手译";Size=new(550,350);MinimumSize=new(450,330);ShowInTaskbar=false;TopMost=true;StartPosition=FormStartPosition.Manual;Font=new("Microsoft YaHei UI",10);Padding=new(20);AutoScaleMode=AutoScaleMode.Dpi;
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6};layout.ColumnStyles.Add(new(SizeType.Percent,100));layout.RowStyles.Add(new(SizeType.Absolute,42));layout.RowStyles.Add(new(SizeType.Absolute,42));layout.RowStyles.Add(new(SizeType.Percent,100));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.Absolute,30));layout.RowStyles.Add(new(SizeType.Absolute,44));Controls.Add(layout);
  var top=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};translate.Text="翻译";explain.Text="解释";translate.Size=explain.Size=new(82,34);translate.Click+=(_,_)=>Switch(TaskMode.Translation);explain.Click+=(_,_)=>Switch(TaskMode.Explanation);top.Controls.AddRange(new Control[]{translate,explain});models.Width=220;models.DropDownStyle=ComboBoxStyle.DropDownList;models.Items.AddRange(catalog.Append(selected).Distinct().Cast<object>().ToArray());models.SelectedItem=selected;models.SelectedIndexChanged+=(_,_)=>{if(!changing&&models.SelectedItem is string id)ModelSelected?.Invoke(id);};top.Controls.Add(models);layout.Controls.Add(top,0,0);
  heading.Dock=DockStyle.Fill;heading.Font=new(Font.FontFamily,15,FontStyle.Bold);heading.TextAlign=ContentAlignment.MiddleLeft;layout.Controls.Add(heading,0,1);
  body.Dock=DockStyle.Fill;body.ReadOnly=true;body.BorderStyle=BorderStyle.None;body.Font=new(Font.FontFamily,12);body.ScrollBars=RichTextBoxScrollBars.Vertical;layout.Controls.Add(body,0,2);
  var originalLayout=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1};expand.Text="展开原文 ▾";expand.AutoSize=true;expand.Click+=(_,_)=>{original.Visible=!original.Visible;expand.Text=original.Visible?"收起原文 ▴":"展开原文 ▾";AdjustHeight();};original.ReadOnly=true;original.Text=text;original.BorderStyle=BorderStyle.None;original.Width=450;original.Height=100;original.ScrollBars=RichTextBoxScrollBars.Vertical;original.Visible=false;originalLayout.Controls.Add(expand);originalLayout.Controls.Add(original);layout.Controls.Add(originalLayout,0,3);
  source.Dock=DockStyle.Fill;source.AutoEllipsis=true;layout.Controls.Add(source,0,4);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};copy.Size=new(115,34);copy.Click+=(_,_)=>{if(results.TryGetValue(Mode,out var r)){Clipboard.SetText(r.Body);copy.Text="已复制 ✓";}};cancel.Text="取消";cancel.Size=new(80,34);cancel.Click+=(_,_)=>CancelRequested?.Invoke();retry.Text="重试";retry.Size=new(80,34);retry.Click+=(_,_)=>RetryRequested?.Invoke();login.Text="重新登录";login.Size=new(95,34);login.Visible=false;login.Click+=(_,_)=>LoginRequested?.Invoke();chooseModel.Text="切换模型";chooseModel.Size=new(95,34);chooseModel.Visible=false;chooseModel.Click+=(_,_)=>ModelsRequested?.Invoke();actions.Controls.AddRange(new Control[]{copy,cancel,retry,login,chooseModel});layout.Controls.Add(actions,0,5);
  ApplyTheme(theme);ShowLoading(selected);
  NativeMethods.GetCursorPos(out var mouse);var area=Screen.FromPoint(new(mouse.X,mouse.Y)).WorkingArea;Location=new(Math.Clamp(mouse.X+12,area.Left,Math.Max(area.Left,area.Right-Width)),Math.Clamp(mouse.Y+12,area.Top,Math.Max(area.Top,area.Bottom-Height)));
 }
 public bool HasResult(TaskMode mode)=>results.ContainsKey(mode);
 void Switch(TaskMode mode){if(Busy||Mode==mode)return;Mode=mode;if(results.TryGetValue(mode,out var result))ShowResult(result);else ModeRequested?.Invoke(mode);}
 public void ShowLoading(string model){login.Visible=chooseModel.Visible=false;Busy=true;translate.Enabled=explain.Enabled=false;copy.Enabled=false;cancel.Visible=true;retry.Visible=false;heading.Text=Mode==TaskMode.Translation?"翻译中…":"解释中…";body.Text="正在处理选中内容";source.Text="本次模型："+model;}
 public void ShowResult(AIResult result){results[result.Mode]=result;login.Visible=chooseModel.Visible=false;Busy=false;translate.Enabled=explain.Enabled=true;cancel.Visible=false;retry.Visible=false;copy.Enabled=true;heading.Text=result.Mode==TaskMode.Translation?"中文翻译":result.Status=="needs_selection"?"请调整选中范围":result.Kind switch{"sentence"=>"句子解释","paragraph"=>"段落解释",_=>"名词解释"};body.Text=result.Body;source.Text="本次模型："+result.Source;copy.Text=result.Mode==TaskMode.Translation?"复制译文":"复制解释";AdjustHeight();}
 public void ShowError(string message,AIError? kind=null){login.Visible=kind==AIError.LoginRequired;chooseModel.Visible=kind==AIError.ModelUnavailable;Busy=false;translate.Enabled=explain.Enabled=true;copy.Enabled=false;cancel.Visible=false;retry.Visible=true;heading.Text="暂时无法完成";body.Text=message;AdjustHeight();}
 void AdjustHeight(){var textHeight=TextRenderer.MeasureText(body.Text,body.Font,new Size(Math.Max(1,ClientSize.Width-40),2000),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl).Height;Height=Math.Clamp(textHeight+LogicalToDeviceUnits(260+(original.Visible?100:0)),LogicalToDeviceUnits(330),LogicalToDeviceUnits(540));var area=Screen.FromControl(this).WorkingArea;Top=Math.Clamp(Top,area.Top,Math.Max(area.Top,area.Bottom-Height));}
 public void ApplyTheme(string id){var palette=Theme.Get(id);palette.Apply(this);source.ForeColor=palette.Muted;}
 public void UpdateModel(string id){changing=true;if(!models.Items.Contains(id))models.Items.Add(id);models.SelectedItem=id;changing=false;}
 protected override bool ShowWithoutActivation=>true;
}
